param([string]$Tag='20261026-final5',[string]$ControlsTag='')
$ErrorActionPreference='Stop';$root=$PSScriptRoot;$out=Join-Path $root 'results';$tag=$Tag;$culture=[cultureinfo]::InvariantCulture
function Number([string]$s){[double]::Parse($s,$culture)}
function Median($values){$v=@($values|Sort-Object);if(!$v.Count){throw 'Empty sample set'};if($v.Count%2){$v[[int][math]::Floor($v.Count/2)]}else{($v[$v.Count/2-1]+$v[$v.Count/2])/2}}
if(!$ControlsTag){
 $receiptPath=Join-Path $out "$tag-environment.json"
 if(Test-Path $receiptPath){$metadata=Get-Content $receiptPath -Raw|ConvertFrom-Json;$ControlsTag=$metadata.controlsTag}
 if(!$ControlsTag){$ControlsTag=$tag}
}
$raw=@();$mpsc=@();$variance=@();$profiles=@();$diagnostics=@();$warms=@();$queueRaw=@()
foreach($run in 1..3){
 foreach($kind in @('core','expanded')){
  foreach($line in Get-Content "$out\$tag-$kind-$run.csv"){
   $p=$line.Split(',')
   if($p[0] -eq 'summary'){$raw+=[pscustomobject]@{run=$run;kind=$kind;name=$p[1];n=[int]$p[2];ratio=(Number $p[6]);aSpread=(Number $p[7]);bSpread=(Number $p[8])}}
   if($p[0] -eq 'sample_diag'){$diagnostics+=[pscustomobject]@{run=$run;kind=$kind;name=$p[1];n=[int]$p[2];aBatch=(Number $p[5]);bBatch=(Number $p[6]);aRounds=(Number $p[4]);bRounds=$(if($p.Count -gt 11){Number $p[11]}else{Number $p[4]});aCpu=(Number $p[7]);bCpu=(Number $p[8]);aCycles=(Number $p[9]);bCycles=(Number $p[10])}}
   if($p[0] -eq 'warm_diag'){$warms+=[pscustomobject]@{run=$run;name=$p[1];n=[int]$p[2];side=$p[3];batches=[int]$p[4];first=(Number $p[5]);last=(Number $p[6])}}
  }
 }
 foreach($line in Get-Content "$out\$tag-mpsc-$run.csv"){$p=$line.Split(',');if($p[0] -eq 'mpsc_summary'){$mpsc+=[pscustomobject]@{run=$run;capacity=[int]$p[1];producers=[int]$p[2];ratio=(Number $p[5]);aSpread=(Number $p[6]);bSpread=(Number $p[7])}}}
 foreach($mode in @('legacy','adaptive','affinity','controlled','isolated','normalized')){
  foreach($line in Get-Content "$out\$ControlsTag-variance-$mode-$run.csv"){$p=$line.Split(',');if($p[0] -eq 'summary'){$variance+=[pscustomobject]@{run=$run;mode=$mode;name=$p[1];n=[int]$p[2];ratio=(Number $p[6]);aSpread=(Number $p[7]);bSpread=(Number $p[8])}}}
 }
 foreach($phase in @('before','after')){
  foreach($line in Get-Content "$out\$ControlsTag-array-$phase-$run.csv"){$p=$line.Split(',');if($p[0] -eq 'profile'){$profiles+=[pscustomobject]@{phase=$phase;run=$run;impl=$p[1];n=[int]$p[2];reserved=[int]$p[4];total=(Number $p[5]);growth=(Number $p[6]);allocate=(Number $p[7]);free=(Number $p[8]);allocations=(Number $p[9]);bytes=(Number $p[10]);relocation=(Number $p[11]);faults=(Number $p[12]);reallocations=(Number $p[15]);moves=(Number $p[16]);movedCapacity=(Number $p[17])}}}
 }
}
# Gate using full batch precision, rather than rounded four-decimal summaries.
foreach($row in $raw){
 $samples=@($diagnostics|Where-Object {$_.run -eq $row.run -and $_.kind -eq $row.kind -and $_.name -eq $row.name -and $_.n -eq $row.n})
 if($samples.Count -ne 15){throw "Incomplete diagnostic samples: $($row.name),$($row.n)"}
 $a=@($samples|ForEach-Object {$_.aBatch/$_.aRounds}|Sort-Object)
 $b=@($samples|ForEach-Object {$_.bBatch/$_.bRounds}|Sort-Object)
 $row.ratio=$a[7]/$b[7];$row.aSpread=$a[13]/$a[1];$row.bSpread=$b[13]/$b[1]
 $row|Add-Member -NotePropertyName aMedian -NotePropertyValue $a[7] -Force; $row|Add-Member -NotePropertyName bMedian -NotePropertyValue $b[7] -Force
}
foreach($row in $mpsc){
 $samples=@(Get-Content "$out\$tag-mpsc-$($row.run).csv"|ForEach-Object {,$_.Split(',')}|Where-Object {$_[0] -eq 'mpsc_raw' -and [int]$_[1] -eq $row.capacity -and [int]$_[2] -eq $row.producers})
 if($samples.Count -ne 15){throw 'Incomplete MPSC raw samples'}
 $a=@($samples|ForEach-Object {Number $_[4]}|Sort-Object);$b=@($samples|ForEach-Object {Number $_[5]}|Sort-Object)
 $row.ratio=$a[7]/$b[7];$row.aSpread=$a[13]/$a[1];$row.bSpread=$b[13]/$b[1]
 $row|Add-Member -NotePropertyName aMedian -NotePropertyValue $a[7] -Force; $row|Add-Member -NotePropertyName bMedian -NotePropertyValue $b[7] -Force
}
function Aggregate($Rows,[string[]]$Keys){
 foreach($g in ($Rows|Group-Object -Property $Keys)){
  $v=@($g.Group|Sort-Object ratio);if($v.Count -ne 3){throw "Missing process result: $($g.Name)"}
  $spread=($v|ForEach-Object {$_.aSpread;$_.bSpread}|Measure-Object -Maximum).Maximum
  $ratio=$v[-1].ratio
  [pscustomobject]@{name=$g.Name;median=$v[1].ratio;min=$v[0].ratio;max=$ratio;spread=$spread;accepted=($ratio -le 1.10 -and $spread -le 1.30);rows=$v}
 }
}
$summary=@(Aggregate $raw @('kind','name','n'))
$queueSummary=@(Aggregate $mpsc @('capacity','producers'))
if($summary.Count -ne 82 -or $queueSummary.Count -ne 4){throw 'Unexpected acceptance case count'}
$accepted=@($summary|Where-Object accepted).Count;$queueAccepted=@($queueSummary|Where-Object accepted).Count
$result=[ordered]@{cases=$summary;queue=$queueSummary;variance=$variance;profiles=$profiles;diagnostics=$diagnostics;warmup=$warms;accepted=$accepted;total=82;queueAccepted=$queueAccepted;queueTotal=4;pass=($accepted -eq 82 -and $queueAccepted -eq 4)}
$result|ConvertTo-Json -Depth 8|Set-Content -Encoding utf8 "$out\$tag-summary.json"
$lines=@('# 고정 용량 MPSC와 배열·측정 편차 수용 — 2026-10-26','','## 판정','',"일반 컨테이너 **$accepted/82**, MPSC **$queueAccepted/4** 조건이 세 프로세스 모두에서 시간 비율과 편차 기준을 충족했다. 기준은 custom/MSVC STL 또는 PPL 중앙값 ≤1.10, 양쪽 15개 표본의 정렬값 x[13]/x[1] ≤1.30이다. 표본 제거·실패 표본 교체·기준 완화는 하지 않았다. 엔진 제품 수용이나 OS 간 성능 동등성을 뜻하지 않는다.",'','독립 솔루션: `C:/Users/idene/source/repos/CreatorEngine/Tests/Containers/build/CreatorContainers.slnx`. 재현: `CreatorContainers/run-mpsc-variance.ps1`, 집계: `summarize-mpsc-variance.ps1`. 원시 자료·컴파일/검사 로그·SHA256은 태그별 `CreatorContainers/results/` 파일이다. 현재 표의 태그는 보고서 파일명과 같다. 이전 소스와 실패한 연결 리스트 후보는 baseline/experiments에 보존했다.','','## 고정 용량 MPSC','','`bounded_mpsc_queue<T,Capacity>`는 고정 값 풀과 FAA publication ring을 직접 보유한다. STL 컨테이너·std::atomic·mutex·TLS·참여자 등록·코어의 힙 할당이 없다. N개 값 저장소와 N개 64비트 epoch/index word를 사용한다. 생성/소멸에는 스레드 접근이 없어야 하고 소비자는 정확히 한 명이어야 한다. 값 생성자/이동 대입/소멸자 자체의 진행 보장은 코어 알고리즘의 보장과 분리한다. 이동 대입/소멸자는 noexcept를 요구한다.','','생산자는 빈 값 슬롯을 CAS로 소유한 뒤 T를 만든다. FAA ticket을 얻고 해당 epoch의 빈 ring word에 인덱스를 CAS로 공개한다. 소비자는 공개 인덱스를 가져오거나 아직 빈 예약을 취소하고 다음 epoch로 넘긴다. 취소된 생산자는 이미 만든 값을 유지한 채 새 ticket에서 다시 공개한다. 따라서 예약한 생산자의 재개를 기다리지 않는다. CAS 공개 실패는 소비자의 epoch 전진을 뜻하며, 풀 탐색은 고정 크기 내에서 종료한다. 소비자는 시작 시 tail snapshot까지만 탐색한다. 성공한 값은 FIFO이고 생산자별 순서도 유지한다. 이는 wait-free 생산자 보장은 아니다.','','`try_push/try_emplace`의 false 또는 `mpsc_push_result::unavailable`은 용량 소진 또는 경합 중 풀 탐색 실패다. false를 관측한 순간 공개 FIFO가 반드시 가득 찼다고 해석하지 않는다. 실패 시 인수를 이동하지 않는다. Capacity에는 생산자가 아직 공개하지 않은 값도 포함된다. 다른 생산자가 소유한 마지막 슬롯을 빼앗는 도움 동작이나 full을 숨기는 임시 힙 할당은 없다. 64비트 ticket/epoch의 명시적 소진 한도에서 예외를 내며, 값을 조용히 덮어쓰지 않는다. 소진 후에는 접근 종료를 확인하고 큐를 다시 생성한다.','','검사: 용량 1/7/256, 4/8생산자 스트레스, 모든 값 유일성·생산자별 FIFO, 전역 FIFO 이력의 선형화 탐색 100회, 이동 전용 소유권·생성 예외·counter 소진. 풀 소유 직후/ticket 예약 직후/공개 직전/공개 직후에 생산자 한 명을 멈춘 채 각 10,000회 전송을 완료했다. MSVC 반복 20회, ASan, ClangCL, Linux Release/ASan+UBSan/TSan을 별도로 실행했다. 검사는 증거이며 모든 가능한 실행의 형식 증명은 아니다.','','초기 Michael–Scott/hazard 후보는 4생산자에서 PPL보다 느려 제외했다. 최종 성능은 128B 값, 생산자별 262,144개, 용량 64/1024, 1P1C/4P1C다. PPL은 기본 무제한 큐이며 자체 큐만 고정 상한을 가진다. full 재시도와 consumer empty 재시도, 전체 128B 검증을 포함한다. 스레드는 먼저 만들고 ready barrier 뒤에 측정을 시작하며 join까지 포함한다. 큐 생성·소멸 비용은 이 전송 표에 포함하지 않는다. 이전 일반 MPMC 수용 보고서를 대체하지 않는다.','','| 용량, 생산자 | 중앙 비율 | 프로세스 범위 | 최대 편차 | 수용 |','|---|---:|---:|---:|---|')
foreach($r in $queueSummary){$lines+='| {0} | {1:F3} | {2:F3}–{3:F3} | {4:F3} | {5} |' -f $r.name,$r.median,$r.min,$r.max,$r.spread,$r.accepted}
$lines+=@('','## 배열 확장과 비용 분리','','기존 1.5배 성장 정책을 유지했다. 분리 계측은 확장 전체 시간, allocator 내부 시간, 해제 시간, 할당/재할당 횟수, 논리적 재배치 요구량, 주소 변경 횟수와 페이지 폴트를 기록한다. 확장 시간은 allocator 비용을 포함하므로 표의 시간들을 서로 더하면 안 된다. memcpy만의 독립 순수 CPU 시간을 측정했다고 주장하지 않는다. 주소 변경 시 old capacity 바이트는 보존 대상량이며 물리 DRAM 전송량은 아니다. 예약 완료 배열을 별도 대조하여 확장 경로를 제거한다.','','기본 heap_allocator는 일반 정렬에 C malloc/realloc/free를 사용한다. trivial이면서 noexcept 이동 가능한 T와 해당 구체 allocator의 명시적 byte_relocation_allocator opt-in에만 byte relocation을 사용하고, 자기 참조 append 인수는 재할당 전에 보존한다. 비단순 객체 또는 reallocate를 제공하지 않는 사용자 allocator는 기존 생성/이동·복사/파괴 경로를 사용한다. 오버얼라인은 정렬 new/delete로 새 공간을 확보해 복사한다. 할당 실패는 원본 저장소를 유지한다. resource_allocator의 가상 메모리 자원 계약은 바꾸지 않았다. 기본 MSVC x64 CRT malloc 정렬 한도는 16B로 고정하고, 다른 런타임은 alignof(max_align_t)를 사용한다. 컴파일러 new-alignment 옵션을 CRT malloc 보장으로 해석하지 않는다. allocator를 상속만 한 타입에는 realloc을 자동 적용하지 않는다. 일반 heap이 전역 operator new hook을 경유한다는 계약은 제공하지 않으므로 엔진 계측에는 명시적 resource를 연결해야 한다. 모든 소비자를 같은 헤더로 재빌드해야 한다.','','| 경로 | N | reserve | 전체 ns 중앙값 | 확장 ns | allocator ns | free ns | 호출수 | 요구 재배치 B | 주소 변경수 | 페이지 폴트 |','|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|')
foreach($g in ($profiles|Group-Object phase,impl,n,reserved)){$v=$g.Group;$lines+='| {0} | {1} | {2} | {3:F0} | {4:F0} | {5:F0} | {6:F0} | {7:F0} | {8:F0} | {9:F0} | {10:F0} |' -f ($v[0].phase+'/'+$v[0].impl),$v[0].n,$v[0].reserved,(Median $v.total),(Median $v.growth),(Median $v.allocate),(Median $v.free),(Median $v.allocations),(Median $v.relocation),(Median $v.moves),(Median $v.faults)}
$lines+=@('','## 편차의 원인과 측정 조건','','초기 계측에서 시간 변화가 CPU cycle 변화와 같이 나타났으므로 전부를 OS 선점 노이즈로 처리하지 않았다. 한 격리 전 예비 표본에서 같은 STL 배열 배치가 약 106ms/391M cycles에서 37ms/136M cycles로 내려갔다. 실행 순서·워밍업·힙 상태와 함께 변했다. NTDLL 내부 경로를 추적하지 않았으므로 특정 힙 분기나 다른 앱의 영향을 단독 원인으로 확정하지 않는다. cold 단일 호출의 시간으로 반복 횟수를 고정하면 실제 표본 길이가 목표 2ms보다 짧아지는 문제도 기록했다. `sample_diag`가 실제 batch ns/반복수/cycle을, `warm_diag`가 측정 직전 고정 워밍업의 첫/마지막 배치를 남긴다. Windows GetThreadTimes는 이 PC에서 약 15.625ms 단위로 관측되어 짧은 표본의 CPU 점유율 산출에는 사용하지 않았다. cycle을 임의로 정확한 CPU 시간으로 환산하지 않았다.','','대조군은 같은 복사 경로 배열/현재 CRT backend에서 기존 보정(legacy) → 실제 batch 목표 시간 보정(adaptive) → 측정 스레드 affinity → affinity+우선순위(controlled) → 구현별 즉시 워밍업·격리(isolated) → 자기 프로세스 힙 캐시 정리(normalized) 순서로 분리한다. 원시 결과는 3개 프로세스를 모두 보존한다. 이 행렬만으로 OS 선점·CPU 주파수·페이지 폴트 각각의 원인을 완전히 계량했다고 주장하지 않는다.','','최종 수용은 측정 스레드만 logical CPU4(선택 mask 로그 참조)에 고정하고 above-normal priority를 사용한다. 다른 앱을 종료하거나 전원·시스템 정책을 바꾸지 않는다. 실제 warmed batch를 영수증의 목표 시간 이상이 되도록 측정 전에 보정한다. 초기 행렬은 20ms, 최종 긴 배치 행렬은 양쪽을 각각 100ms 이상으로 보정한다. 구현별 반복 수를 기록하고 1회 작업당 ns로 정규화한다. 같은 반복 수를 강제하여 느린 쪽의 배치가 속도 비율만큼 길어지는 조건은 피했다. 공통 반복 수의 final3은 프로세스 1 도중 중단했으며 원본과 중단 사유를 보존했다. A/B를 매 표본 교대하여 힙 상태를 계속 흔드는 대신, 각 구현 바로 앞에 고정 1초 워밍업을 하고 15개 표본을 연속 수집한다. 프로세스 2는 B/A 순서로 반전한다. 통계 저장 벡터 네 개는 측정 전에 reserve(15)하여 표본 사이 재할당을 없앤다. 각 일반 구현 워밍업 직전에 자기 프로세스 HeapOptimizeResources를 호출한다. LFH 강제 활성화는 최종 조건에 포함하지 않는다. MPSC 생산자들은 소비자와 다른 물리 코어에 배치한다. 모든 정식 표본을 사용하며 느린 값을 지우지 않는다. 이는 warm-throughput 수용 조건이다. cold start/혼합 힙/엔진 프레임 p99는 별도 조건이다.','','| 대조 모드, 작업 | 세 프로세스 최대 custom 편차 | 최대 STL 편차 |','|---|---:|---:|')
foreach($g in ($variance|Group-Object mode,name,n)){$v=$g.Group;$lines+='| {0} | {1:F3} | {2:F3} |' -f $g.Name,($v.aSpread|Measure-Object -Maximum).Maximum,($v.bSpread|Measure-Object -Maximum).Maximum}
$lines+=@('','## 안정된 기준에서 드러난 해시맵 병목','','중간 정규화 측정 두 프로세스는 map_miss/4096에서 약 1.26~1.31 비율로 실패했다. 양쪽 편차가 작아 실제 성능 문제로 분류했다. 해시 상위 7비트 태그만 추가한 후보는 equality 호출을 192,000→1,664회로 줄였지만, 별도 4,096 키 probe의 자체 시간은 1.449ms→1.687ms로 나빠졌다. 태그만으로 해결했다고 결론내리지 않았다.','','최종 후보는 8개 제어 바이트를 uint64로 읽어 SWAR로 태그 일치/empty를 찾는다. 첫 empty 이전 후보만 equality를 호출하고 wrap 구간에는 첫 8바이트의 복제본을 사용한다. home 슬롯 hit를 먼저 확인하고, capacity≤128에는 기존 짧은 scalar 경로를 유지한다. 같은 고정 seed probe의 최종 자체 시간은 약 0.666ms(4,096), 12.016ms(65,536), STL 대비 약 0.405/0.318이었다. 이 probe는 메인 전체 RNG fixture와 다르므로 수용 판정은 아래 82개 전체 비교를 따른다. wrap/tombstone/clear/copy/rehash 회귀와 sanitizer를 함께 검사했다. `20261026-map-before/after/grouped/hybrid*.csv`, `experiments/20261026-map-scalar`에 실패 후보와 분리 계측을 보존했다.','','## 측정 해석과 재현 한계','','초기 20261026 행렬은 일반 74/82, MPSC 3/4로 실패했다. 구현 보완 뒤 20ms 20261026-final2 전체 행렬은 일반 77/82, MPSC 4/4였고 일반 82개 모두 시간 비율은 충족했으나 5조건에서 편차가 초과했다. 이어진 20261026-final은 두 프로세스 후 안정적인 map_miss 실패를 확인하여 중단했고 원본을 유지했다. 최종 태그는 명시한 조건의 전체 재실행이다. 동일 바이너리의 실패 표본을 선택 교체한 결과가 아니다. 작은 20조건 probe는 통계 버퍼 reserve 유무와 힙 정리 유무 모두 통과했다. 따라서 표본 중 재할당 제거는 확인한 측정 간섭 제거지만 이것만을 편차의 유일한 원인으로 확정할 수 없다.','','HeapOptimizeResources는 호출 프로세스의 사용하지 않는 힙 캐시를 정리한다. API 의미는 [Microsoft HeapSetInformation](https://learn.microsoft.com/windows/win32/api/heapapi/nf-heapapi-heapsetinformation)을 따른다. MSVC x64 malloc 16B 정렬은 [Microsoft malloc](https://learn.microsoft.com/en-us/cpp/c-runtime-library/reference/malloc?view=msvc-170) 계약이다. 최종 표는 이 프로토콜에서의 warm throughput이다. 혼합 할당/실제 엔진 작업 부하에서 동일 결과를 보장하지 않는다.','','라이브러리 공개 헤더를 고정한 final2의 MSVC 전체 CTest는 10/10, MPSC 추가 반복은 20회다. ClangCL 및 MSVC ASan은 일반/확장/MPSC/Windows 헤더 조합/정렬 검사, Linux는 Release와 ASan+UBSan에서 일반/확장/MPSC/정렬(기본 및 -fnew-alignment=64)을 각 5회, TSan은 MPSC 5회를 검사한다. sanitizer 로그는 20261026-final2 태그에 보존한다. 이후 변경은 측정 helper와 스크립트이며, final4에서 MSVC CTest 10/10을 다시 실행했다. 두 영수증의 include 헤더 해시가 일치하는지 별도 대조한다. 공개 헤더별 독립 컴파일도 수행한다.')
$lines+=@('','## 배치 길이 대조','','`experiments/20261026-batch-window`는 같은 실행 파일에서 CE_BENCH_BATCH_NS만 20ms/100ms로 바꿨다. 할당 없는 map_miss/64, map_hit/8, array_growth/65536, radix_sort_u64/256을 각각 새 프로세스에서 3번 측정했고 프로세스 2는 A/B와 창 길이 순서를 반전했다. 20ms는 12조건 중 11개, 100ms는 12개 모두 기준을 충족했다. 최대 양쪽 편차는 1.4367→1.1311이었다. 20ms 실패는 array_growth 자체 구현 쪽 편차다. 표본을 버리지 않았고 편차 한도는 1.30 그대로다. 이 분리 실행은 전체 메인 RNG fixture의 정확한 복제가 아니므로 전체 판정은 본문의 82조건 행렬을 따른다.','','긴 배치는 짧은 간섭을 한 표본 안에서 평균화하는 조건 변경이다. OS 선점·SMT 경합·주파수·IRQ 중 어느 하나를 단독 원인으로 증명한 것이 아니다. 실패 이후의 CPU 카운터 snapshot에서 측정 논리 코어 100%, 그 형제 0%, processor performance 약 117%를 관측했지만 실패 구간과 동기화된 기록이 아니므로 원인 판정에 쓰지 않는다. 조회처럼 할당 없는 조건도 흔들렸으므로 모든 편차를 힙 문제로 환원하지 않는다. 결과는 백그라운드 앱을 종료하지 않은 이 PC에서의 명시된 warm-throughput 조건이다.')
if($tag -eq '20261026-final5'){
 $lines+=@('','## 조건별 새 프로세스 격리','','100ms 독립 보정의 연속 실행 final4는 81/82, MPSC 4/4였다. 마지막 프로세스의 map_miss/65536에서 STL 편차 1.354가 초과했다. 같은 바이너리·입력의 단독 프로세스 3회에서는 비율 약 0.331–0.337, 최대 양쪽 편차 1.119로 통과했다. 이 추가 검사만을 전체 통과로 바꾸지 않았다.','','최종 final5는 통과/실패 여부로 조건을 고르지 않고 일반 82개 전부를 조건별 새 프로세스에서 3회(총 246개 프로세스) 측정한다. 프로세스당 하나의 벤치마크만 활성화하고 입력 생성은 건너뛰지 않는다. main.cpp와 library_benchmark.cpp의 RNG는 정확성/fixture 생성에 있으며 벤치마크 람다에서 전역 RNG를 진행하지 않는다. 반복 2는 조건 순서와 A/B 순서를 모두 반전한다. 모든 조건은 양쪽 15표본을 유지하고 같은 1.10/1.30 기준을 적용한다. MPSC는 기존 4조건을 프로세스당 측정하여 총 3프로세스다.','','바이너리는 final4와 동일하며 새 컴파일이나 라이브러리 변경은 없다. 개별 원본은 results/20261026-final5-cases, 집계 입력은 final5-core/expanded-{1..3}.csv다. 재현은 run-isolated-acceptance.ps1이다. 원인 대조 행렬과 배열 profile은 controlsTag=20261026-final4의 원본을 참조하며 이름을 바꿔 복사하지 않는다. 여러 작업을 연속 실행한 상태와 조건별 격리를 분리한 증거이며, 단일 OS/힙/하드웨어 원인을 형식적으로 확정한 것은 아니다.')
}
$lines+=@('','## 일반 컨테이너 최종 표','','| 작업, N | 중앙 비율 | 프로세스 범위 | 최대 편차 | 수용 |','|---|---:|---:|---:|---|')
foreach($r in ($summary|Sort-Object name)){$lines+='| {0} | {1:F3} | {2:F3}–{3:F3} | {4:F3} | {5} |' -f $r.name,$r.median,$r.min,$r.max,$r.spread,$r.accepted}
$lines+=@('','## 프로세스 간 절대 시간 차이','','수용 기준의 1.30은 각 프로세스 안의 15표본 x[13]/x[1]이다. 프로세스 간 중앙값의 max/min을 같은 통계로 혼동하지 않는다. 아래 배열 비교에는 절대 중앙값도 남긴다. 기준 통과가 프로세스 간 절대 시간이 완전히 일정해졌다는 뜻은 아니다. allocator/주소 배치/상태 차이를 모두 제거했거나 OS·SMT·주파수·IRQ의 원인을 완전히 분해했다는 주장도 하지 않는다.','','| 작업, N | 자체 중앙값 ns 범위 | STL 중앙값 ns 범위 | 자체 프로세스 max/min | STL 프로세스 max/min |','|---|---:|---:|---:|---:|')
foreach($case in ($summary|Where-Object {$_.name -like 'core, array_*'})){
 $a=@($case.rows.aMedian|Sort-Object);$b=@($case.rows.bMedian|Sort-Object)
 $lines+='| {0} | {1:F0}–{2:F0} | {3:F0}–{4:F0} | {5:F3} | {6:F3} |' -f $case.name,$a[0],$a[-1],$b[0],$b[-1],($a[-1]/$a[0]),($b[-1]/$b[0])
}
$lines+=@('','## 통합 경계','','이번 변경은 독립 솔루션 안의 구현·정확성·위 조건의 성능 검증이다. 엔진 PPL 별칭과 실제 소비자는 아직 바꾸지 않았다. 실제 소비자의 bounded overflow 정책·메모리 소유권·스레드 수명·모듈 ABI를 확인한 뒤 한 곳씩 A/B 적용하고 씬 전환·종료·프레임 검증을 수행한다. Windows x64/MSVC의 독립 결과이며 WSL Clang은 정확성/sanitizer 대상이다. macOS/GCC/ARM64 및 OS 간 성능 일관성은 미검증이다.')
$lines+=@('','프로파일러 통합 후보를 소스에서 확인했다. `Engine/EngineDiagnostics/ProfileService.h`의 collector_work는 frame/counter/control/barrier를 함께 보관한다. `ProfileService.cpp`의 프레임 enqueue는 프레임 수 한도를 검사하지만 wait_until_idle barrier와 제어 명령은 같은 규칙으로 드롭하지 않는다. 큐 외의 m_queuedFrames, pending gap, control ticket, semaphore와 종료 상태를 함께 동기화한다. 따라서 deque를 고정 MPSC로 단순 치환하거나 실패 반환을 무시하지 않는다. 이 소비자 변경은 이번에 수행하지 않았으며 실제 엔진 검증도 실행하지 않았다.','','빌드 환경 참고: MSVC 명령에는 로컬 vcpkg의 추가 include 경로가 들어있지만, container_tests/library_benchmark/mpsc_benchmark의 실제 CL.read 의존 파일 목록에는 vcpkg 경로가 없었다. 라이브러리는 엔진 헤더나 vcpkg 패키지를 요청하지 않는다. 실행한 세 성능 타깃의 컴파일 명령은 태그별 *-compile.tlog에 보존한다. Release /O2 /Ob2, /W4 /WX, /std:c++latest(CMake cxx_std_23), iterator debug 0 조건이다. 다른 진단 실행 파일의 해시는 디렉토리 inventory이며 모두 이 최종 helper로 재빌드했다는 뜻이 아니다.')
$lines|Set-Content -Encoding utf8 "$out\MPSC_VARIANCE_REPORT_$tag.md"
Write-Output "General $accepted/82; MPSC $queueAccepted/4; PASS=$($result.pass)"
